/* animation/anim-library.js — Meshy-style local animation library UI.
 * Uses the real clips already loaded/generated by FbxRig or RigAutoGen;
 * no fake remote/API result is shown.
 */
(function () {
  'use strict';
  const U = PixiStudio.Utils;
  const bus = PixiStudio.bus;
  const Library = { query: '', category: 'All', speed: 1, loop: true };

  const META = [
    { id: 'Running', label: 'Running', category: 'Locomotion', tags: 'run sprint locomotion' },
    { id: 'Walk', label: 'Walk', category: 'Locomotion', tags: 'walk locomotion' },
    { id: 'Sprint', label: 'Sprint', category: 'Locomotion', tags: 'run fast locomotion' },
    { id: 'Idle', label: 'Idle', category: 'Idle', tags: 'idle breathe rest' },
    { id: 'Attack', label: 'Attack', category: 'Combat', tags: 'attack strike combat' },
    { id: 'Combo', label: 'Combo', category: 'Combat', tags: 'combo combat' },
    { id: 'Dodge', label: 'Dodge', category: 'Combat', tags: 'dodge roll combat' },
    { id: 'Victory', label: 'Victory', category: 'Emote', tags: 'victory emote' },
    { id: 'Dance', label: 'Dance', category: 'Emote', tags: 'dance emote' }
  ];

  function entries() {
    const rig = PixiStudio.FbxRig && PixiStudio.FbxRig.loaded ? PixiStudio.FbxRig.generated :
      (PixiStudio.RigAutoGen && PixiStudio.RigAutoGen.current ? PixiStudio.RigAutoGen.current.clips : []);
    return META.map(function (m) {
      const hit = rig && rig.find(function (x) { return x.id === m.id || x.name === m.id; });
      return hit ? Object.assign({}, m, { clip: hit }) : null;
    }).filter(Boolean);
  }

  Library.play = function (id) {
    if (PixiStudio.FbxRig && PixiStudio.FbxRig.loaded) {
      PixiStudio.FbxRig.play(id);
    } else if (PixiStudio.AnimAutoGen && PixiStudio.RigAutoGen && PixiStudio.RigAutoGen.current) {
      PixiStudio.AnimAutoGen.play(id);
    } else if (PixiStudio.Anim && PixiStudio.Anim.applyPreset) {
      const map = { Running: 'run', Walk: 'walk', Sprint: 'run', Idle: 'idle', Attack: 'attack', Combo: 'combo', Dodge: 'dodge', Victory: 'victory', Dance: 'dance' };
      PixiStudio.Anim.applyPreset(map[id] || 'idle');
    }
    if (PixiStudio.Anim) { PixiStudio.Anim.setSpeed(Library.speed); PixiStudio.Anim.setLoop(Library.loop); }
    bus.emit('animation:library-played', { id: id, speed: Library.speed, loop: Library.loop });
  };

  Library.renderPanel = function () {
    const body = document.getElementById('animation-page-body');
    if (!body) return;
    const old = document.getElementById('meshy-animation-library');
    if (old) old.remove();
    const section = U.el('div', { class: 'section-block', id: 'meshy-animation-library' });
    section.appendChild(U.el('div', { class: 'section-head' }, [U.el('span', { html: U.icon('animation') }), U.el('span', { text: '🎬 Animation Library — Meshy workflow' })]));
    const sc = U.el('div', { class: 'section-content' });
    const search = U.el('input', { class: 'input', placeholder: 'Search animation: run, attack, dance…', value: Library.query, style: 'margin-bottom:7px;' });
    search.addEventListener('input', function () { Library.query = search.value.toLowerCase(); draw(); });
    sc.appendChild(search);
    const cats = ['All', 'Locomotion', 'Idle', 'Combat', 'Emote'];
    const chips = U.el('div', { class: 'chip-row', style: 'margin-bottom:7px;' });
    cats.forEach(function (cat) { const b = U.el('button', { class: 'chip' + (Library.category === cat ? ' active' : ''), text: cat }); b.onclick = function () { Library.category = cat; draw(); }; chips.appendChild(b); });
    sc.appendChild(chips);
    const controls = U.el('div', { style: 'display:flex;gap:6px;align-items:center;margin-bottom:7px;' });
    const speed = U.el('input', { type: 'range', min: '0.25', max: '2.5', step: '0.05', value: String(Library.speed), class: 'slider' });
    const speedText = U.el('span', { class: 'dim small', text: Library.speed.toFixed(2) + 'x' });
    speed.oninput = function () { Library.speed = parseFloat(speed.value); speedText.textContent = Library.speed.toFixed(2) + 'x'; if (PixiStudio.Anim) PixiStudio.Anim.setSpeed(Library.speed); };
    const loop = U.el('label', { class: 'dim small', style: 'display:flex;gap:4px;align-items:center;' });
    const cb = U.el('input', { type: 'checkbox' }); cb.checked = Library.loop; cb.onchange = function () { Library.loop = cb.checked; if (PixiStudio.Anim) PixiStudio.Anim.setLoop(Library.loop); }; loop.appendChild(cb); loop.appendChild(U.el('span', { text: 'Loop' }));
    controls.appendChild(U.el('span', { class: 'dim small', text: 'Speed' })); controls.appendChild(speed); controls.appendChild(speedText); controls.appendChild(loop); sc.appendChild(controls);
    const grid = U.el('div', { class: 'mt-grid', style: 'grid-template-columns:repeat(3,1fr);gap:5px;' }); sc.appendChild(grid);
    function draw() {
      chips.querySelectorAll('.chip').forEach(function (b, i) { b.classList.toggle('active', cats[i] === Library.category); });
      grid.innerHTML = '';
      entries().filter(function (e) { return (Library.category === 'All' || e.category === Library.category) && (!Library.query || (e.label + ' ' + e.category + ' ' + e.tags).toLowerCase().indexOf(Library.query) >= 0); }).forEach(function (e) {
        grid.appendChild(U.el('button', { class: 'mt-btn' + (PixiStudio.FbxRig && PixiStudio.FbxRig.current === e.id ? ' primary' : ''), html: U.icon(e.category === 'Combat' ? 'swords' : e.category === 'Emote' ? 'flower' : 'character') + '<span>' + e.label + '</span>', onclick: function () { Library.play(e.id); draw(); } }));
      });
      if (!grid.children.length) grid.appendChild(U.el('div', { class: 'dim small', text: 'Clip chưa sẵn sàng cho rig hiện tại. Hãy Load FBX hoặc Auto-Rig trước.' }));
    }
    draw(); section.appendChild(sc); body.insertBefore(section, body.firstChild);
  };
  window.PixiStudio.AnimLibrary = Library;
})();
